// The flag stays set until the timer's callback runs the queue, as a scheduler's message loop does.
let running = false
const queue = []
exports.schedule = (work) => {
  queue.push(work)
  if (!running) {
    running = true
    setTimeout(() => {
      running = false
      while (queue.length > 0) queue.shift()()
    }, 100)
  }
}
